"""Build the paginated reading edition from the project's recorded experiments."""
from pathlib import Path
import html

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'docs/notes'
OUT.mkdir(exist_ok=True)
PAGES = []
BASE = 'https://github.com/lakshya-asu/ffc-insertion-research/blob/30b6a78e25d1245a07bffad7d2b0dc52705a8e56/'

def ref(path, label):
    return f'<a href="{BASE}{path}">{label}</a>'

def fig(path, caption, height=260):
    return f'<figure><img src="{path}" style="height:{height}px"><figcaption>{caption}</figcaption></figure>'

def table(headers, rows):
    return '<table><thead><tr>'+''.join(f'<th>{x}</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table>'

def note(title, text):
    return f'<aside><b>{title}</b><p>{text}</p></aside>'

def page(kicker, title, lead, body, sources='', cls=''):
    n=len(PAGES)+1
    PAGES.append(f'<section class="page {cls}" id="p{n}"><header><span>FFC / FIELD NOTES</span><span>RESEARCH EDITION 01</span></header><main><div class="kicker">{kicker}</div><h1>{title}</h1><p class="lead">{lead}</p>{body}</main><footer><span>{sources or "FR3 · DESK-TO-PCB ASSEMBLY"}</span><span>{n:02d}</span></footer></section>')

def flow(labels, subtitle=''):
    # Vertical diagram; actual text, vector lines, and explicit scope labels.
    h=len(labels)*70+10
    s=f'<svg class="diagram" viewBox="0 0 660 {h}" role="img" aria-label="{html.escape(subtitle)}"><defs><marker id="arr" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#19776d"/></marker></defs>'
    for i,(name,desc) in enumerate(labels):
        y=5+i*70
        s+=f'<rect x="2" y="{y}" width="656" height="52" rx="4" fill="{("#e8f2ef" if i%2==0 else "#f2f0e9")}"/><text x="20" y="{y+22}" font-size="15" font-weight="600">{html.escape(name)}</text><text x="20" y="{y+41}" font-size="12" fill="#55625f">{html.escape(desc)}</text>'
        if i<len(labels)-1:s+=f'<path d="M330,{y+53} v16" stroke="#19776d" stroke-width="1.4" marker-end="url(#arr)"/>'
    return s+'</svg>'

page('THE RESEARCH NOTEBOOK', 'Teaching a robot<br>to connect a<br>ribbon cable.', 'From a loose cable on the desk to a verified PCB connection.',
     fig('../live/mount/03-cell.webp','The current FR3 / Zero 2 W workcell. A static Isaac Sim rendering; no insertion is occurring.',350)+
     '<div class="cover-bottom"><p>Simulation, perception, mechanics<br>and the path to learned assembly.</p><p>28 September 2026 · UTC<br>Snapshot through commit 30b6a78</p></div>'+note('Where we are','The mounted macro camera now delivers guarded ROS2 observations. Entrance perception, cable mechanics and contact control still need to be joined into a sensor-driven skill.'), cls='cover')

page('READING GUIDE', 'A map of the work.', 'This is a project notebook you can read away from the terminal. It explains what we built, why we changed direction, and what the evidence actually supports.',
     '<div class="toc">'+''.join(f'<a href="#p{n}"><span>{title}</span><b>{n:02d}</b></a>' for n,title in [(3,'The task and the meaning of success'),(4,'What is working today'),(5,'Hardware and workpieces'),(6,'The cable and connector geometry'),(7,'Why we added a macro camera'),(8,'How the camera is mounted'),(9,'The complete system architecture'),(10,'ROS2 and the classical vision frontend'),(11,'What the transport tests found'),(12,'How perception evolved'),(13,'DINOv3 results and their limits'),(14,'How we will train the new macro model'),(15,'The cable physics work so far'),(16,'From a mechanics model to a usable skill'),(17,'Pickup, presentation and held-end inspection'),(18,'Alignment, contact, seating and recovery'),(19,'The learning roadmap'),(20,'The evaluation plan'),(21,'The next milestones and open decisions'),(22,'Running, reviewing and extending the work'),(23,'Sources, provenance and a short glossary')])+'</div>'+note('How to read the labels','“Tested” refers to a stated simulation or software test. “Assumed” marks geometry or parameters that have not been identified from the actual part. “Planned” describes work that is not implemented yet. Rendered images throughout this document are simulation evidence.'),cls='contents')

page('01 / TASK CONTRACT','The whole assembly<br>is the goal.','We want the robot to begin with an ungrasped ribbon cable on a desk and finish with a correctly seated, secured and independently verified connection.',
     '<p>The initial benchmark uses one separated cable, a fixed PCB and controlled lighting. Both cable ends are free. We will vary desk position, orientation, which face is up, and bounded curl. Clutter, tangled cables, an attached far end and a freely moving PCB are later extensions that need their own tests.</p>'+
     table(['Skill','Evidence needed to move on'],[
     ('See the entrance','Visible upper and lower rims, cable leading edge and latch state; freshness and uncertainty checks.'),
     ('Pick up the cable','Separation from the desk, a stable grasp, no unacceptable slip and enough exposed end.'),
     ('Inspect and orient','Correct contact face and usable end pose; ambiguity triggers another view or regrasp.'),
     ('Align without contact','Image-based relative pose inside a justified capture region, with the path still clear.'),
     ('Contact and insert','Bounded motion with observed progress and a tested stop-and-retract response.'),
     ('Seat and latch','Separate seating and latch evidence, followed by an electrical or functional check when available.'),
     ('Recover and repeat','Failures detected, classified and handled within a fixed retry budget.')])+
     '<h2>What counts as success</h2><p>A completed command is not assembly evidence. Final verification must distinguish seating, latch closure, tool release, electrical function and damage. Simulation currently has no qualified electrical contact model. We can demonstrate mechanical subskills while keeping that final criterion explicitly unresolved.</p>'+note('The agreed development order','We are still developing Step 1, entrance observation, entirely in simulation. Historical handling experiments inform the design but do not qualify the new Pi task.'),ref('task-specification.md','Task contract')+' · '+ref('experiments/017-entrance-feature-perception.md','Simulation-first scope'))

page('02 / CURRENT STATUS','A useful foundation.<br>An unfinished assembly skill.','The project has reproducible scenes, tested observation software and several informative mechanical experiments. The current Pi cell has no active robot-control endpoint.',
     table(['Area','Recorded status','What it does not establish'],[
     ('Scene and CAD','Pi 4 / Camera Module 3 and Zero 2 W assets imported; current mount study uses Zero 2 W.','Certified connector internals or manufacturing tolerances.'),
     ('Camera mount','45° view; full-tool geometry; sampled arm clearance and continuous tool/cable translation bounds.','A fabricated bracket, stiffness, or full-cell collision certification.'),
     ('ROS2 observations','Native RGB, CameraInfo, fixed camera TF, preprocessing and health supervision work.','Dynamic sensor timing or control-rate performance.'),
     ('Perception','Pretrained DINOv3 entrance-feature study completed on earlier optics.','A trained/evaluated model for the current mounted macro view.'),
     ('Mechanics','Segmented cable benchmarks and historical generic handling runs recorded.','Pi cable laminate calibration, reliable contact insertion or damage prediction.'),
     ('Tactile and force','Needed interfaces and experimental roles identified.','A selected, calibrated tactile device or functioning sensor model.'),
     ('Learning and action','Skill curriculum and observation boundary defined.','A trained action policy, VLA controller or RL insertion agent.')])+
     '<h2>The latest completed milestone</h2><p>Thirty-five consecutive processed observations arrived from the mounted macro simulation at roughly 1.2 fps. Publication-to-observation age was 22.5–44.9 ms in that short test. The 500 ms freshness guard correctly reports stale intervals between rendered frames.</p><p>The repository suite passed 97 tests, the ROS frontend passed three additional unit tests, and an isolated DDS fault suite passed eight cases. These are software checks; they do not measure physical assembly reliability.</p>',ref('experiments/020-native-camera-ros2.md','Native camera / ROS2 evidence'))

page('03 / HARDWARE','What is selected,<br>and what is still a concept.','The user selected the Franka FR3. The original US$20,000 budget was subsequently set aside; there is no verified procurement quote or complete bill of materials.',
     table(['Component','Choice or role','Status'],[
     ('Robot','Franka FR3; vendor FR3 v2.1 geometry and kinematics in Isaac.','Simulation asset selected.'),
     ('Primary workpieces','Pi 4 Model B + Camera Module 3; Zero 2 W for the current sideways-entry study.','Imported scenes; physical parts not qualified here.'),
     ('Macro camera','Basler ace 2 a2A2448-75ucBAS; Sony IMX547 color global shutter.','Simulation reference; no purchase.'),
     ('Macro lens','Kowa LM35JC10M, 35 mm C-mount; 0.38× at 100 mm front working distance.','Nominal optics and dimensioned envelope.'),
     ('Overview cameras','Manual-focus Arducam reference for desk and broader entrance views.','User’s exact model/lens remains unidentified; B0498 / IMX585 was a simulation reference.'),
     ('End effector','Offset suction-to-pinch tool with deployment and clamp actuation.','Research mechanism; no commercial actuator SKU selected.'),
     ('Fixture and lighting','Fixed PCB supports, braced macro stand, optional passive presentation shelf; diffuse illumination.','Placement concepts; detailed hardware and lighting selection open.'),
     ('Contact instrumentation','Measured jaw state, vacuum status, fingertip contact/slip and robot/wrist contact evidence.','Required capabilities; device selection and calibration open.')])+
     '<h2>The later press-on task</h2><p>The phone-style flex connector presses down onto a PCB. It has different capture, seating and release mechanics from a side-entry ZIF cable. We will select a representative coupon and qualify it separately; no phone connector model or assembly result is claimed.</p>',ref('config/macro-mounted-camera.json','Selected optical profile')+' · '+ref('experiments/013-pi-zero-side-entry.md','Zero task'))

page('04 / WORKPIECE MODEL','A detailed PCB still needs<br>a trustworthy opening.','The Zero 2 W model is visually rich enough for scene development. Its original connector mesh did not expose the separate physical features needed for entrance perception.',
     fig('../live/mount/03-macro.webp','Current near-entry RGB. The socket and cable are static proxies, rendered with uncalibrated finite-aperture blur.',245)+
     '<div class="cols"><div><h2>The board</h2><p>We extracted the named Zero 2 W assembly from the community Optocam Zero STEP model. It contains 94 leaf components and 478,024 triangles. Its 65 × 30 mm outline and 58 × 23 mm mounting-hole pattern were checked against the official mechanical drawing.</p><p>The assembly names a Molex 54548-2271 connector. That name does not certify the production Pi BOM. The original socket was a fused mesh with no articulated slider.</p></div><div><h2>The replacement socket</h2><p>An engineered substitute keeps the board context while making upper and lower entrance rims and the slider explicit. Its 11.7 mm opening width, 0.5 mm opening height and 0.8 mm slider travel are assumptions.</p><p>The slider is visually positioned in open/closed states. Contact springs, clamping and insertion resistance are not yet modeled as functioning mechanics.</p></div></div>'+
     '<h2>The cable</h2><p>The Zero reference is the 200 mm Standard–Mini family: 22 contacts at 0.5 mm pitch on one end and 15 at 1 mm on the other. The revision-two outline is 11.5 mm wide along most of its length, widening to 16 mm. Body thickness (0.14 mm), header thickness (0.30 mm), exposed length and stiffener dimensions remain modeling assumptions. The internal conductor routing and layered mechanics are unresolved.</p>',ref('experiments/013-pi-zero-side-entry.md','CAD and cable provenance')+' · '+ref('experiments/017-entrance-feature-perception.md','Socket audit'))

page('05 / OPTICS','Look into the entrance.','A whole-socket mask can tell us where the connector is. Insertion needs evidence about the small opening, the cable edge and what the gripper hides as it approaches.',
     table(['Parameter','Selected simulation reference'],[
     ('Active image','2448 × 2048 pixels; 2.74 µm pitch'),('Lens and working distance','35 mm nominal; 0.38× magnification; 100 mm from lens front'),('Normal-plane field of view','17.651 × 14.767 mm'),('Nominal object sampling','7.211 µm per pixel, before optical blur and oblique projection'),('Starting hardware settings','30 fps target; 500 µs exposure; 0 dB gain; fixed manual focus; physical f/8'),('Automatic controls','Exposure and gain off; white balance locked after calibration'),('Current rendering rate','About 1.2 fps in the mounted ROS preview; not the hardware target')])+
     '<h2>How the simulated lens is constructed</h2><p>A thin-lens equivalent matches the nominal magnification. It uses an object distance of 127.105 mm and image distance of 48.3 mm, placing the inferred principal plane 27.105 mm behind the lens front. The renderer uses an equivalent f-number of 11.04 to preserve the assumed pupil diameter of physical f/8.</p><p>The approximate one-pixel depth-of-field calculation gives 0.419 mm total, ignoring diffraction. A separate diffraction estimate gives an Airy diameter near 5.4 pixels at 550 nm. Pixel sampling therefore cannot be treated as resolved feature size or metrology accuracy.</p>'+note('Settings to test, not an optical calibration','The renderer has no calibrated MTF, diffraction, Bayer response, sensor noise or exposure radiometry. The 30 fps / 500 µs settings are starting hardware targets. Focus, aperture and lighting still need a task-specific comparison under tool occlusion and glare.')+
     '<p>We chose a conventional perspective macro lens for the first integration because it fits an ordinary camera-calibration model. A telecentric design remains an option if later measurements justify its different projection model and larger envelope.</p>',ref('experiments/018-macro-camera.md','Optics calculations and manufacturer references'))

page('06 / MOUNTING','The complete tool<br>changed the camera angle.','The original 25° view looked useful with small finger proxies. Once the full offset tool was included, it hid the entrance. We moved to 45° elevation.',
     '<div class="cols">'+fig('../live/mount/rejected-25deg.webp','Rejected: 25° with the complete tool. Zero labeled rim or leading-band pixels remained in the visibility probe.',215)+fig('../live/mount/03-macro.webp','Selected: 45° near-entry view. The lower rim remains small, even when unobstructed.',215)+'</div>'+
     '<p>The stand sits opposite the wrist, on the negative-Y side of the PCB. It uses a 30 mm square-section upright and cross-arm, a diagonal brace, a tilt saddle and an adapter envelope. The PCB supports and stand share a baseplate. A separate keep-out volume reserves USB plug, service-loop and strain-relief space.</p>'+
     table(['Check','Result','Scope'],[
     ('Clearance','17.000 mm minimum projected separating gap','211 sampled IK poses; enclosing robot/tool/hardware boxes.'),
     ('Translation sweep','17.000 mm lower bound','Continuous nominal tool and rigid-cable translations; robot links remain sampled.'),
     ('Assembly allowance','15 mm remaining after assumed 2 mm budget','Compared with a 5 mm study requirement; not measured accuracy.'),
     ('Feature retention','Upper rim 99.76%; lower rim 95.26%; leading band 100%','One 0.3 mm-gap pose versus a matching no-tool view; geometric labels only.')])+
     '<p>The lens front sits about 70.7 mm above and 70.7 mm horizontally from the target. The planned route withdraws, shifts sideways, then lifts. A direct lift under the camera is outside that route. Fasteners, bracket stiffness, all-cell collisions and latch contact remain unqualified.</p>',ref('experiments/019-macro-mount.md','Mount design, failures and clearance audit'))

page('07 / ARCHITECTURE','What the robot may know.','The observation boundary is a central design decision: the future policy must operate from measurements that could exist on the real workcell.',
     flow([('Sensors and calibration','RGB + CameraInfo + fixed camera TF are active. Robot, tool and tactile streams are planned.'),('Observation health and classical vision','Validate timing and calibration; rectify RGB; preserve geometry through resize.'),('Learned perception and state estimation','Estimate entrance rims, cable end, contact face, latch and uncertainty from sensor history.'),('Skill supervisor and bounded policy','Choose inspect, regrasp, align, insert or retract from observed evidence.'),('Robot / tool controllers','Apply bounded commands; monitor measured response and contact. Not connected today.'),('Independent verification and episode log','Keep seating, latch, electrical function, damage and failure reasons separate.')],'Target sensor-driven architecture')+
     '<div class="cols"><div><h2>Runtime inputs</h2><p>Images, calibration, acquisition timestamps, measured robot/tool state and appropriately modeled contact or tactile measurements. The estimator should expose uncertainty and missing evidence.</p></div><div><h2>Offline information</h2><p>USD geometry, instance masks and exact object poses may generate supervised labels and score predictions. They must not enter the deployed estimator, policy, critic, rewards or skill transitions.</p></div></div>'+note('Separate the display from the controller','The live website can show the whole simulator scene to a human. That observer view does not grant the action policy access to simulator truth. The website remains read-only.'),ref('SENSOR_FIRST.md','Observation boundary')+' · '+ref('experiments/020-native-camera-ros2.md','Implemented ROS path'))

page('08 / ROS2 + CLASSICAL VISION','Carry the image geometry<br>all the way through.','The native camera pipeline is implemented in a separate ROS2 Jazzy container. Its input is rendered RGB and camera calibration; it has no scene or offline-label mount.',
     table(['Channel / object','Content and behavior'],[
     ('/cell/cameras/macro/image_raw','2448 × 2048 RGB8 with acquisition stamp and macro_optical_frame.'),
     ('/cell/cameras/macro/camera_info','Matching stamp, native intrinsics, distortion and image dimensions.'),
     ('/tf_static','Fixed world-to-camera optical calibration; no object-pose publication.'),
     ('/cell/cameras/macro/observation','Atomic RGB + edges + transformed CameraInfo + quality values and revision IDs.'),
     ('/cell/diagnostics','Accepted/rejected counts, image statistics and watchdog reasons.'),
     ('/cell/task/status','observation_only or stale; motion_permitted remains false.')])+
     '<h2>The classical frontend</h2><p>Exact timestamp pairing comes first. The node then validates frame identity, native dimensions, encoding, payload size, calibration and age. It rejects duplicates, reordered timestamps, frames older than 500 ms, timestamps more than 5 ms into the future, and changes to an already accepted intrinsic calibration.</p><p>OpenCV rectifies the image, halves it with area interpolation and adds four black pixels at each side. The resulting 1232 × 1024 image is divisible by the DINOv3 patch size. Intrinsics use the same pixel-center mapping; the calibrated image center becomes (615.75, 511.75) for the current profile.</p><p>Canny edges and brightness/sharpness diagnostics accompany the RGB. We have not enabled arbitrary sharpening or contrast enhancement. The planned learned input is RGB; whether extra edge channels help requires a controlled experiment.</p>'+note('Remaining interface work','The calibration hash covers intrinsics, not extrinsics, and the source-profile string is configured. Mount changes need an explicit calibration review. FeatureFrame and TactileFrame are message contracts only; learned macro inference and tactile publication are inactive.'),ref('experiments/020-native-camera-ros2.md','ROS2 implementation')+' · '+ref('ros2_ws/src/ffc_cell/ffc_cell/cv_frontend.py','Frontend source'))

page('09 / TRANSPORT EVIDENCE','Small messages worked.<br>The image needed more room.','The first ROS test discovered its peers but did not deliver the 15 MB native image. Testing the actual payload exposed a problem that a heartbeat-only check would have missed.',
     '<div class="metrics"><div><strong>35</strong><span>consecutive processed frames</span></div><div><strong>1.19</strong><span>approximate frames / second</span></div><div><strong>22.5–44.9</strong><span>publication age in milliseconds</span></div></div>'+
     '<p>The explicit Fast DDS profile allocates a 128 MiB shared-memory segment with a 16 MiB maximum message size. The containers share host IPC and use localhost discovery. A second issue caused lost image/calibration pairs with depth-one input queues; retaining four input samples resolved it in the subsequent live check. The output still retains only the latest observation.</p>'+
     table(['Fault injected','Observed result'],[
     ('Valid native image and calibration','Processed observation emitted; source timestamp preserved.'),('Stale acquisition timestamp','No observation emitted.'),('Wrong optical frame','No observation emitted.'),('Changed intrinsic calibration','No observation emitted.'),('Image / CameraInfo timestamp mismatch','No synchronized observation emitted.'),('Blank image','No observation emitted.'),('Camera dropout','Supervisor reports stale; motion remains false.'),('Fresh valid recovery','Observation health recovers; motion remains false.')])+
     '<h2>What the latency number means</h2><p>The stamp is assigned after the static render returns. The measured age covers publication, transport, processing and observation receipt; it excludes the preceding render time and is not exposure-to-control latency. A dynamic simulator will need a consistent simulation clock and an acquisition-time contract.</p><p>At about 1.2 fps, the next frame arrives after the 500 ms freshness deadline. The alternating stale status is expected and remains visible. We have not relaxed the guard to make the dashboard appear healthier.</p>',ref('experiments/020-native-camera-ros2.md','Transport and timing report'))

page('10 / PERCEPTION HISTORY','Better masks helped.<br>They did not finish the task.','We began with whole-component segmentation, then narrowed the objective to the physical features that constrain insertion.',
     '<div class="timeline"><div><b>Early small segmentation baseline</b><p>Established image capture, offline labels, isolated inference and held-out review. Cable, contacts, stiffener and board sockets were component classes. Their centroids were review measurements, not grasp points.</p></div><div><b>DINOv2 component model</b><p>A frozen foundation encoder and task head improved the Zero component masks. A later two-head model was evaluated against the older model on the same 240 independent test images.</p></div><div><b>A reliability gate that abstained</b><p>Pooled foreground mean IoU improved from 91.16% to 93.74%; mini-end IoU improved from 80.92% to 88.87%. Neither camera met the calibration rule of zero bad accepts and at least 20 accepted views. Both policies abstained on every test image.</p></div><div><b>DINOv3 entrance features</b><p>After official access was approved, pretrained ViT-B/16 features supported separate rim, leading-band and slider classes. The task and geometry changed, so these results are not a controlled DINOv2-versus-DINOv3 comparison.</p></div><div><b>Mounted macro domain</b><p>The camera, projection, view angle, preprocessing and full-tool occlusion are now different. A new dataset and frozen-model test are required before connecting inference.</p></div></div>'+
     '<h2>SAM 3.1</h2><p>The official checkpoint was downloaded and GPU inference was made to run in its own container. The initial six probes contained no cable/socket target and returned empty masks. That is a compatibility check on negative scenes, not demonstrated localization performance. Any future prompts must be fixed or image-derived, never supplied from simulator boxes or points.</p>',ref('experiments/015-zero-reliability.md','DINOv2 reliability')+' · '+ref('experiments/016-entrance-and-grasp.md','Model access and probes'))

page('11 / DINOv3 RESULTS','The thin cable feature<br>is still the difficult part.','The earlier camera study used official frozen DINOv3 features with an RGB-detail decoder. It learned useful rim structure, but the leading band and latch decisions remain weak.',
     '<div class="cols">'+fig('../live/entrance-features/0000-entrance-rgb.webp','A held-out RGB frame from the earlier camera domain.',145)+fig('../live/entrance-features/0000-entrance-prediction.webp','The corresponding learned overlay. Colors indicate classes.',145)+'</div>'+
     table(['Feature','Pooled IoU','Mean visible-image IoU'],[
     ('Upper entrance rim','89.2%','85.4%'),('Lower entrance rim','88.7%','78.0%'),('Cable leading band','39.3%','32.3%')])+
     '<p>The selected focal-loss candidate used 120 epochs and validation-only checkpoint selection. It was frozen before a fresh test set of 48 scenes / 96 camera images was generated. Development contained 120 scenes, with both views of each scene kept in the same split. The change in epoch budget means the result is not a loss-only ablation.</p><p>Provisional slider classification was correct in 52 of 81 visibly labeled images, unknown in 10 and wrong in 19. Fifteen images had no observable slider label; no slider false positive was reported for those images. These small counts do not establish reliable latch verification.</p><h2>How to interpret the scores</h2><p>Pooled IoU accumulates pixels before computing overlap, so larger visible features have more influence. Mean visible-image IoU weights each qualifying image equally. Both describe mask overlap; neither is a metric error in the cable-tip frame.</p>'+note('Keep the label definition in view','The “leading edge” class is actually a 0.3 mm-long band at the beginning of the stiffener, retaining its normal material. It is not the mathematical edge or a verified 3D insertion target. These scores belong to the earlier fixed 4K camera crop, not the current macro camera.'),ref('experiments/017-entrance-feature-perception.md','Frozen DINOv3 feature test'))

page('12 / NEXT PERCEPTION EXPERIMENT','Train through the camera<br>we intend to use.','The next dataset must include the selected 45° mount and complete tool. The old crop model cannot be silently applied to the new 2448 × 2048 sensor profile.',
     flow([('Capture development scenes','Native RGB and offline feature labels; keep scene siblings in one split.'),('Audit labels and inputs','Check absent objects, occlusion, geometry, hashes and preprocessing consistency.'),('Train and select on validation','Frozen DINOv3 encoder first; task decoder; record source and checkpoint hashes.'),('Freeze the entire candidate','Weights, preprocessing, prompts, thresholds, calibration and class definitions.'),('Generate an independent final test','Run RGB-only inference in isolation; score labels offline and inspect failures.')],'Mounted camera training protocol')+
     '<h2>Variation that matters</h2><p>Include board translation and small rotations, cable skew, different approach gaps, jaw setback, partial occlusion, dim light, glare, focus drift and absent cable/socket cases. Keep image visibility realistic: hidden features receive no visible-pixel label. Do not change a material’s color just to make a class easier to detect.</p><p>Training must use the same rectification, area resize, padding and pixel-center calibration as the live frontend. Record every random seed and camera profile. Exposure and blur variations are sensitivity tests until the optical model is calibrated.</p><h2>The acceptance report</h2><p>Report each rim separately, thin-band errors, boundary displacement, empty-view false positives and latch errors. Also report abstention coverage and failures among accepted views. Before action, convert observed feature uncertainty into a justified relative-pose uncertainty; an attractive overlay is insufficient.</p>',ref('experiments/020-native-camera-ros2.md','Next acceptance gate'))

page('13 / MECHANICS HISTORY','The physics had to earn<br>our trust too.','Early videos looked plausible while the cable sag was badly wrong. Independent numerical references exposed that error and changed the solver configuration.',
     '<h2>Segmented ribbon model</h2><p>The historical generic cable was a chain of rigid segments with rotational compliance. A 50 mm benchmark used a nominal homogeneous 8 mm-wide, 0.3 mm-thick strip with E = 3 GPa. These parameters are assumptions for that benchmark; they are not the material specification of the current Raspberry Pi cable.</p>'+
     table(['Short-span timestep / iterations','Sag','Error against discrete reference'],[
     ('4.1667 ms / 32','13.361 mm','+2,391%'),('0.25 ms / 128','0.83577 mm','+55.8%'),('0.125 ms / 255','0.61686 mm','+15.0%'),('0.0625 ms / 255','0.56130 mm','+4.6%')])+
     '<p>Those rows held the spring stiffness fixed. The discrete chain reference accounts for its own boundary conditions; comparing it only with a continuum formula would conceal part of the numerical error.</p><h2>The later full-span check</h2><p>An independent nonlinear energy minimization gave 46.1317 mm tip sag for the 150 mm chain. The selected PGS profile—8 kHz, 255 position iterations and four velocity iterations—gave 46.0810 mm in an awake repeat, about −0.110%. The static benchmark used extra body drag solely to remove transient motion. That drag is not permitted as a general handling shortcut.</p><h2>Native surface FEM</h2><p>The shell benchmark also showed timestep, mesh and iteration sensitivity. Its reported sag/reference ratios ranged from 1.323 to 1.906 across the stated cases. Full native-shell handling was not implemented or qualified. Static agreement in a segmented model does not establish contact force, twist, damping or laminate behavior.</p>',ref('experiments/005-numerical-validation.md','Numerical sweeps')+' · '+ref('experiments/007-contact-and-transport.md','Selected solver'))

page('14 / PHYSICS ROADMAP','Realism needs several<br>separate checks.','We need a model that reproduces the behaviors the controller depends on: bending, twist, grip slip, edge contact, buckling and seating resistance.',
     table(['Model layer','What to establish before relying on it'],[
     ('Cable shape and inertia','Correct outline, mass distribution, thickness, stiffeners and a justified bending/twist response.'),
     ('Laminate reference','An offline layered model or suitable mechanical reference for copper/polymer structure and end reinforcement.'),
     ('Contact thickness','No tunneling through the desk, jaw or entrance; inspect collision offsets at the relevant scale.'),
     ('Grip behavior','Finite normal force, translation and rotation slip, release and changing unsupported length.'),
     ('Connector resistance','Entrance edges, internal contacts and latch mechanics that generate plausible force/displacement behavior.'),
     ('Sensor rendering','Observed force/tactile signals with defined frames, bias, filtering, rate and uncertainty.'),
     ('Numerical convergence','Timestep, mesh and solver sweeps across bending and contact cases; energy and penetration diagnostics.')])+
     '<h2>Use expensive models as references</h2><p>A detailed FEA model can support offline coupon studies, such as cantilever deflection, twist or controlled edge compression. A faster reduced model may be more practical for learning rollouts if it matches the reference over the task’s operating range. We have not established a validated layered FEA model for this Pi cable.</p><p>Before physical specimens are available, numerical convergence, analytic references and documented parameter ranges can support a bounded simulation proof of concept. Results must retain those assumptions. Physical transfer later needs measured bend/twist, grip-slip and insertion force/displacement data.</p>'+note('Do not fit one successful animation','Changing friction or stiffness until one insertion succeeds can hide a model error. Hold out mechanical cases and preserve failures. The earlier guide-rod collision, changing clamp preload and solver sensitivity all produced convincing-looking but invalid intermediate results.'),ref('experiments/006-handoff-and-solver-audit.md','Handoff and mechanics audit')+' · '+ref('experiments/017-entrance-feature-perception.md','Open physics gates'))

page('15 / PICKUP + PRESENTATION','Get hold of the cable<br>without hiding its end.','The research tool first lifts the cable by suction, then places a lower jaw beneath it for a finite-force mechanical pinch. The unsupported end must remain visible and stable.',
     fig('../live/mount/03-placement.webp','Complete tool and stand envelopes. The current static scene does not demonstrate a physical grasp.',240)+
     '<div class="cols"><div><h2>Direct handoff</h2><p>Acquire an insulated region, lift enough to deploy the lower jaw, close with suction still supporting the cable, verify retention, then release vacuum. Observe slip during the subsequent raise and approach.</p><p>It avoids an extra placement but asks the tool to handle more of the initial curl and orientation variation.</p></div><div><h2>Passive presentation fixture</h2><p>Place and support the cable, release it, then regrasp in a more repeatable pose. The fixture may improve visibility and exposed-length control, at the cost of another contact and recovery stage.</p><p>The user requested a comparison of both routes before choosing the final mechanism.</p></div></div>'+
     '<h2>What the historical trials showed</h2><p>After substantial solver and tool corrections, one generic direct sequence completed in 41.760 simulated seconds; one fixture sequence completed in 66.789 seconds. Both reached about 3.801 mm geometric depth. These runs used privileged cable-tip state and an open clearance slot with zero cable/connector contact. They establish neither a camera-driven Pi skill nor a reliability ranking.</p><p>The next pickup study must measure acquisition, slip, exposed length, orientation and damage proxies separately. A stable hold should be verified before the robot enters the camera’s close approach corridor. Vacuum pressure, jaw load/displacement and tactile slip are required sensing roles, not active devices today.</p>',ref('experiments/007-contact-and-transport.md','Historical direct / fixture results')+' · '+ref('experiments/016-entrance-and-grasp.md','Visibility tradeoff'))

page('16 / ACTION SKILLS','Approach in small steps,<br>and verify each transition.','The first action baseline should begin with a securely held cable near an open connector. Desk pickup and full-task composition follow once that smaller problem works from sensor feedback.',
     '<h2>Inspect and orient</h2><p>Move the held end into a repeatable inspection view. Estimate the leading edge, contact face, orientation and visible deformation. A single oblique image can leave depth ambiguous; another calibrated view or deliberate small viewpoint change may be needed. If the estimate remains ambiguous, regrasp or stop.</p><h2>Align without touching</h2><p>Use visual feedback to reduce relative position and angle error while keeping a known clearance. Evaluate against independently held-out reference poses offline. Set the capture region from the assumed simulation geometry with explicit uncertainty; revise it when real dimensions become available. Mask IoU is not an alignment tolerance.</p><h2>Contact and insertion</h2><p>Advance with short bounded commands and watch both image progress and contact response. Detect edge catches, skew, buckling, slipping and blocked entry. A recovery should stop, unload and retract along a tested route before attempting another observation or alignment. Actual force thresholds remain unset until the selected model and later specimens support them.</p><h2>Seating and latch</h2><p>Hold the cable while checking seating evidence. Operate the latch as a separate skill with its own tool access, contact model and failure modes. Verify again after release: a cable can move while the tool withdraws or while the latch closes.</p>'+note('Contact and tactile sensing','A useful contact interface reports measured quantities with timestamps, units and sensor-frame transforms. Fingertip sensing should help distinguish stable grip from slip; insertion contact sensing should help distinguish progress from edge loading. Publishing ground-truth penetration or fabricated zero readings would not satisfy this contract.')+
     '<p>The controller must remain bounded under lost tracking, stale frames and sensor disagreement. Robot-side stop behavior and communication-loss behavior need tests independent of the learned policy.</p>',ref('task-specification.md','Skill preconditions and failure handling')+' · '+ref('SENSOR_FIRST.md','Control gates'))

page('17 / LEARNING','Learn one observable<br>skill at a time.','No action policy has been trained for the current Pi cell. The planned progression makes it possible to identify whether a failure comes from sensing, mechanics, control or learning.',
     table(['Stage','Experiment','Fair comparison'],[
     ('Sensor-driven baseline','A bounded visual/contact controller for pre-grasped alignment, then insertion and recovery.','Same sensor streams and verified success criteria as later policies.'),
     ('Behavior cloning','Train on successful and corrective demonstrations generated through sensor feedback.','Hold out starts, offsets and failure cases; count intervention and retries.'),
     ('Action-sequence policies','Compare action chunking or a diffusion policy if temporal prediction helps.','Same demonstrations, observations, reset distribution and evaluation budget.'),
     ('Residual RL','Learn limited corrections around a working controller.','Bounded actions; sensor-conditioned actor, critic and rewards; independent outcomes.'),
     ('Whole-task coordination','Join pickup, inspection, alignment, insertion, latching and recovery.','Evaluate each stage and full-task completion, including failed acquisitions.'),
     ('Optional VLA','Study language-conditioned task choice or broader object generalization.','Compare against the smaller policy on tasks where language adds measurable value.')])+
     '<h2>What goes into the policy</h2><p>Use calibrated image history, robot/tool measurements, contact/tactile history, observation health and task context. The state estimator may summarize recent evidence and uncertainty. Exact cable vertices, hidden insertion depth or a true latch transform must not become actor, critic, reward or transition shortcuts.</p><h2>What earns reward</h2><p>Use observable progress and independently checked outcomes. Test any learned success detector on deliberately bad assemblies before letting it provide rewards. Without a qualified electrical model, simulation cannot award electrically complete assembly success.</p><p>Isaac Lab is a candidate framework for later task orchestration and rollout training; it is not integrated in the recorded milestone. The expensive 8 kHz historical physics profile must be profiled and, if needed, replaced by a separately qualified faster model before choosing a training budget.</p>',ref('docs/architecture/index.html','Learning discussion and research links'))

page('18 / EVALUATION','Make failures part<br>of the experiment.','A useful result needs a declared test distribution, a fixed policy and a denominator that includes failed pickups, timeouts and interventions.',
     table(['Test family','Variation / deliberate fault','Record'],[
     ('Entrance observability','Glare, rotation, defocus, gripper approach, missing target.','Feature visibility, boundary error, wrong detections and abstention.'),
     ('Pickup and grip','Position, face up/down, curl, grasp setback and exposed length.','First-attempt lift, slip, drop, deformation and damage proxies.'),
     ('Held-end estimate','Orientation ambiguity, partial occlusion, change of view.','Relative-pose error, uncertainty coverage and regrasp rate.'),
     ('Alignment','Lateral/vertical offset, yaw/roll, calibration perturbation.','Residual error before contact and false readiness decisions.'),
     ('Contact','Edge hit, skew, blocked slot, cable buckle and slip.','Detection delay, peak modeled load, retract outcome and repeated failure.'),
     ('Latch and verification','Shallow seating, failed closure, movement on release.','False success, missed failure and verification disagreement.'),
     ('System faults','Stale/reordered frames, lost tracking, delayed or missing contact data.','Stop latency, safe state, recovery and retained evidence.')])+
     '<h2>Split the data by scene and episode</h2><p>Multiple camera views of the same scene belong together. Freeze weights, preprocessing, thresholds and prompt rules before the independent test. Preserve failed runs instead of overwriting them. Inspect difficult cases as images and trajectories, not only as average scores.</p><h2>Report more than a success percentage</h2><p>Include sample count, first-attempt completion, completion within a fixed retry budget, intervention rate, time and failure category. For selective perception, report accepted coverage alongside error among accepted cases. An always-abstain model can avoid bad accepts while providing no useful decisions.</p><p>Domain randomization should vary plausible uncertainty and preserve physical correlations. Cable thickness changes mass, stiffness and mating clearance together. Randomization cannot repair a missing contact mechanism or an unrealistic sensor channel.</p>',ref('experiments/015-zero-reliability.md','Selective evaluation lessons')+' · '+ref('task-specification.md','Episode data contract'))

page('19 / NEXT MILESTONES','What we do next,<br>and what unlocks motion.','The native ROS camera milestone is complete. The next increment is a new mounted-camera perception study, followed by a sensor-driven pre-contact skill.',
     '<ol class="milestones"><li><b>Mounted-camera development set</b><p>Capture full-tool approaches and the agreed perturbations. Audit native images, feature labels, absent targets and split separation. Keep the optical assumptions attached to the data.</p></li><li><b>Frozen DINOv3 macro candidate</b><p>Train with the live OpenCV transform, select on validation, freeze all runtime components, then capture and score a fresh final test. Compare SAM only with fixed or image-derived prompts.</p></li><li><b>Relative-pose estimator</b><p>Turn visible edges into a calibrated cable-to-mouth estimate with uncertainty. Establish when another view is necessary. Test without touching the connector.</p></li><li><b>Mechanics and sensor qualification</b><p>Resolve finite-thickness cable contact, bending/twist, grip slip and connector resistance. Define realistic tactile/contact outputs and their timing. Qualify the full approach and retract geometry.</p></li><li><b>Pre-grasped sensor-driven insertion</b><p>Demonstrate bounded alignment, contact, progress detection and recovery across declared variation. Keep latch and final verification separate.</p></li><li><b>Complete the desk-to-PCB chain</b><p>Add pickup, orientation, fixture comparison, latching and release. Only then evaluate the entire task and begin controlled learning comparisons.</p></li></ol>'+
     '<h2>Decisions still open</h2><p>Commercial gripper/actuator selection; tactile technology and placement; insertion-contact sensing; exact Arducam identification; manufacturable mount and fixture details; lighting hardware; connector internals and material parameters. None should be silently treated as a purchased, calibrated component.</p>'+note('Hardware comes later','Real-camera and bench tests are deferred by agreement. We can continue a clearly bounded simulation proof of concept now, then use physical measurements to revise geometry, optics, mechanics and thresholds before transfer.'),ref('experiments/020-native-camera-ros2.md','Immediate next gate')+' · '+ref('LAB_LIVE.md','Working agreements'))

page('20 / WORKING WITH THE PROJECT','Keep the evidence<br>easy to revisit.','The repository, live site and experiment records serve different purposes. Use the records when you need to distinguish a tested result from an illustrative rendering.',
     '<h2>Read and watch</h2><p><a href="https://lakshya-asu.github.io/ffc-insertion-research/live/">Live lab</a> shows the cell, current work and curated reviews. <a href="https://lakshya-asu.github.io/ffc-insertion-research/architecture/">Architecture</a> explains the longer-term system. The <a href="https://github.com/lakshya-asu/ffc-insertion-research">source repository</a> contains code, experiment notes and configuration. Older pages may describe an earlier milestone; this notebook resolves the current status through commit 30b6a78.</p><p>The live feed is a stationary rendered scene. Its images carry freshness information; when rendering pauses, the page retains a saved frame. Browser notes are local to that browser and are not an agent inbox. There is no actuator or terminal endpoint on the public site.</p><h2>Runtime pieces</h2>'+
     table(['Container / environment','Purpose'],[
     ('ffc-isaac:6.1.0','USD scenes, renderer, historical physics and current native camera publisher.'),('ffc-foundation:4.57.6','Pinned foundation-model runtime used for DINO feature studies.'),('ffc-sam3:2345a4a','Separate SAM 3.1 compatibility/inference environment.'),('ffc-ros2:jazzy-dinov3','ROS2 Jazzy, OpenCV frontend, observation supervisor and model dependencies.'),('Local Python / CAD environments','Source tests, audits, STEP conversion, reports and publishing.')])+
     '<h2>Start the current ROS setup</h2><pre>docker build -f Dockerfile.ros2 \\&#10;  -t ffc-ros2:jazzy-dinov3 .&#10;docker compose -f compose.yaml -f compose.ros2.yaml \\&#10;  up -d perception&#10;docker compose -f compose.yaml -f compose.ros2.yaml \\&#10;  run --rm experiment</pre><p class="small">These commands assume the existing Isaac image and scene assets. Do not start a second renderer over the live preview. Follow LAB_LIVE.md to stop it cleanly first.</p><p>Every experiment gets a fresh output directory, frozen source/configuration references, raw observations, diagnostic results and verified media. Preserve failures. Historical state-driven experiments require deliberate selection and must remain separate from the new observation-only pipeline.</p>',ref('LAB_LIVE.md','Live operation')+' · '+ref('experiments/020-native-camera-ros2.md','ROS reproduction'))

page('REFERENCE DESK','Sources, provenance<br>and useful terms.','This edition synthesizes the repository’s recorded experiments and the decisions in our conversation. It does not claim a new hardware test or an independent literature review.',
     '<div class="cols"><div><h2>Project evidence</h2><ul class="sources">'+''.join('<li>'+ref(p,t)+'</li>' for p,t in [('task-specification.md','Task contract and verification'),('experiments/005-numerical-validation.md','E005 · Numerical validation'),('experiments/006-handoff-and-solver-audit.md','E006 · Handoff and static shape'),('experiments/007-contact-and-transport.md','E007 · Contact and transport'),('experiments/013-pi-zero-side-entry.md','E013 · Zero CAD and cable'),('experiments/015-zero-reliability.md','E015 · Selective perception'),('experiments/017-entrance-feature-perception.md','E017 · DINOv3 feature evaluation'),('experiments/018-macro-camera.md','E018 · Macro optics'),('experiments/019-macro-mount.md','E019 · Mount and clearance'),('experiments/020-native-camera-ros2.md','E020 · Native ROS camera')])+'</ul><h2>Primary references in those records</h2><ul class="sources"><li><a href="https://docs.baslerweb.com/a2a2448-75ucbas">Basler camera specification</a></li><li><a href="https://www.kowa-lenses.com/LM35JC10M-2-3-35mm-10MP-C-Mount-Lens/10707">Kowa lens specification</a></li><li><a href="https://datasheets.raspberrypi.com/rpizero2/raspberry-pi-zero-2-w-mechanical-drawing.pdf">Zero 2 W mechanical drawing</a></li><li><a href="https://www.molex.com/en-us/products/part-detail/545482271">Molex 54548-2271 reference</a></li><li><a href="https://github.com/facebookresearch/dinov3">Official DINOv3 implementation</a></li><li><a href="https://github.com/facebookresearch/sam3">Official SAM implementation</a></li><li><a href="https://fast-dds.docs.eprosima.com/en/2.6.x/fastdds/xml_configuration/transports.html">Fast DDS transport configuration</a></li></ul></div><div><h2>Plain-language glossary</h2><dl><dt>FFC / FPC</dt><dd>Flat cable / flexible printed circuit. Similar appearance does not establish the same construction.</dd><dt>ZIF</dt><dd>A connector mechanism intended to accept a cable with its latch open, then secure it.</dd><dt>IoU</dt><dd>Overlap between predicted and labeled pixels, divided by their union.</dd><dt>Privileged state</dt><dd>Simulator information unavailable as a direct real sensor measurement.</dd><dt>FEM / FEA</dt><dd>A discretized mechanical model / its analysis. Accuracy still requires verification and validation.</dd><dt>Abstention</dt><dd>Declining to make an actionable prediction when evidence is inadequate.</dd><dt>TF / CameraInfo</dt><dd>ROS coordinate transforms / image calibration metadata.</dd><dt>Held-out test</dt><dd>Data excluded from training, model selection and threshold tuning.</dd></dl></div></div>'+
     '<div class="license"><b>Image attribution</b><p>Zero PCB geometry derives from Doruk Kumkumoglu’s <a href="https://github.com/dorukkumkumoglu/optocamzero">Optocam Zero</a>, CC BY-SA 4.0. Changes include board extraction, USD tessellation, scene placement, lighting and added cable/camera/tool geometry. Derived scene images retain <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a>. FR3 geometry comes from the official Franka simulation asset; the tool and stand are project design envelopes. This notebook’s original prose and diagrams are also offered under CC BY-SA 4.0, excluding third-party material subject to its own terms.</p></div>', 'SOURCE SNAPSHOT · 30b6a78 · 28 SEP 2026 UTC',cls='references')

